#!/usr/bin/env bash
set -euo pipefail
repo="$(cd "$(dirname "$0")/.."&&pwd)";root="${1:-$repo/build/fg_conv/macos-custom-conv2/attempt-$(date -u +%Y%m%dT%H%M%SZ)}";[[ ! -e "$root" ]]||{ echo "Attempt exists" >&2;exit 2;};src="$repo/src/fg_conv";model="$repo/build/fg_default_readback/eval0-default-all-a5-a/runtime-default-buffers-post-evaluate-0";build="$root/build";mkdir -p "$build";xcrun -sdk macosx metal -std=metal3.1 -I "$src" -c "$src/custom_conv2.metal" -o "$build/kernel.air";xcrun -sdk macosx metallib "$build/kernel.air" -o "$build/kernel.metallib";xcrun clang++ -std=c++20 -fobjc-arc -Wall -Wextra -Werror -Wno-unused-function "$src/macos_custom_conv2_probe.mm" -framework Foundation -framework Metal -o "$build/host"
for launch in $(seq 60 67);do layer=l$launch;wt=$((118+4*(launch-60)));bt=$((wt+2));lr="$root/$layer";mkdir -p "$lr";for poison in a5 5a;do for ord in a b;do id="$layer-poison-$poison-process-$ord";run="$lr/$id";mkdir -p "$run";"$build/host" "$layer" "$build/kernel.metallib" "$model/default-token-$(printf '%06d' "$wt").bin" "$model/default-token-$(printf '%06d' "$bt").bin" "$run" "$id" "$poison">"$run/stdout.log" 2>"$run/stderr.log";done;done;python3 "$repo/scripts/verify-fg-custom-conv2.py" backend --backend mac --layer "$layer" --root "$lr" --output "$lr/backend-receipt.json";done;echo "attempt_root=$root";echo result=pass
